using System;using System.IO;using Frociart;
internal static class CodeTemplateSmokeTests {
 static int Main(string[] args){try{var program=FlowSource.Compile(FlowPseudocode.Decode("x=2\nSTAMPA x+1"));foreach(var target in FlowSourceTarget.All){var code=target.Generate(program);var template=FlowCodeTemplate.Create("Prova "+target.Name,target.Id,target.Extension,"Prova",(target==FlowSourceTarget.Python?"#":"//")+" Mio modello\n{{ source }}");var generated=template.Generate(program,code);if(!generated.Text.EndsWith(code.Text)||generated.ForBlock(null,program.Scopes[0].Blocks[1].Id).Count==0)throw new Exception("Mapped full-source template "+target.Id);File.WriteAllText(Path.Combine(args[0],"smoke."+target.Extension),generated.Text);}
 var report=FlowCodeTemplate.Create("Inventario","custom","txt","", "{{ project.title }}\n{% for scope in program.scopes %}{{ scope.name }}\n{% for block in scope.blocks %}{{ loop.index }}: {{ block.kind }} {{ block.text }}\n{% endfor %}{% endfor %}");var text=report.Generate(program,null);if(!text.Text.Contains("process")||text.ForBlock(null,program.Scopes[0].Blocks[1].Id).Count==0)throw new Exception("Raw IR template mapping");Console.WriteLine("CODE_TEMPLATE_SMOKE PASS");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
